7|export class Input {
8|  constructor() {
9|    this.down = new Set();
10|    this.queue = [];
11|    window.addEventListener('keydown', (e) => {
12|      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
13|      if (!e.repeat) this.queue.push(e.code);
14|      this.down.add(e.code);
15|    });
16|    window.addEventListener('keyup', (e) => this.down.delete(e.code));
17|    window.addEventListener('blur', () => this.down.clear());
18|  }
19|
20|  axis(pos, neg) {
21|    return (this.down.has(pos) ? 1 : 0) - (this.down.has(neg) ? 1 : 0);
22|  }
23|
24|  held(code) {
25|    return this.down.has(code);
26|  }
27|
28|  consume() {
29|    const q = this.queue;
30|    this.queue = [];
31|    return q;
32|  }
33|
34|  clear() {
35|    this.down.clear();
36|    this.queue.length = 0;
