40|export class Flight {
41|  constructor() {
42|    this.pos = new THREE.Vector3();
43|    this.prevPos = new THREE.Vector3();
44|    this.quat = new THREE.Quaternion();
45|    this.forward = new THREE.Vector3(0, 0, -1);
46|    this.right = new THREE.Vector3(1, 0, 0);
47|    this.up = new THREE.Vector3(0, 1, 0);
48|    this.bank = 0;
49|    this.pitch = 0;
50|    this.heading = 0;
51|    this.verticalSpeed = 0;
52|    this.reset();
53|  }
54|
55|  reset() {
56|    this.pos.set(START.x, START.y, START.z);
57|    this.prevPos.copy(this.pos);
58|    this.quat.identity();
59|    this.speed = 62;
60|    this.throttle = 0.6;
61|    this.boost = 0;
62|    this.health = 100;
63|    this.fuel = 86;
64|    this.ammo = 120;
65|    this.crashed = false;
66|    this.hardLanding = false;
67|    this.flash = 0;
68|    this.updateVectors();
69|  }
70|
71|  updateVectors() {
72|    this.forward.set(0, 0, -1).applyQuaternion(this.quat).normalize();
73|    this.right.set(1, 0, 0).applyQuaternion(this.quat).normalize();
74|    this.up.set(0, 1, 0).applyQuaternion(this.quat).normalize();
75|    this.heading = (THREE.MathUtils.radToDeg(Math.atan2(this.forward.x, -this.forward.z)) + 360) % 360;
76|    this.bank = Math.atan2(this.right.y, this.up.y);
77|    this.pitch = Math.asin(THREE.MathUtils.clamp(this.forward.y, -1, 1));
78|  }
79|
80|  applyPose(x, y, z, headingDeg = 0, pitch = 0, roll = 0) {
81|    this.pos.set(x, y, z);
82|    this.prevPos.copy(this.pos);
83|    const e = new THREE.Euler(pitch, THREE.MathUtils.degToRad(-headingDeg), roll, 'YXZ');
84|    this.quat.setFromEuler(e);
85|    this.updateVectors();
86|  }
87|
88|  update(dt, input) {
89|    this.prevPos.copy(this.pos);
90|
91|    // Throttle
92|    this.throttle = clamp(this.throttle + input.throttle * dt * 0.5, 0.04, 1);
93|
94|    // Afterburner
95|    const wantBoost = input.boost && this.fuel > 0.5;
96|    this.boost = damp(this.boost, wantBoost ? 1 : 0, wantBoost ? 5 : 3.2, dt);
97|    this.fuel = clamp(this.fuel - (this.boost * 2.1 + 0.16) * dt, 0, 100);
98|
99|    const targetSpeed = 31 + this.throttle * 60 + this.boost * 40;
100|    this.speed = damp(this.speed, targetSpeed, 1.15, dt);
101|
102|    // Local rotations: pitch (X), yaw (Y), roll (Z).
103|    const q = new THREE.Quaternion();
104|    const pitchRate = input.pitch * 1.05 + (this.speed - 58) * 0.0026;
105|    q.setFromAxisAngle(new THREE.Vector3(1, 0, 0), pitchRate * dt);
106|    this.quat.multiply(q);
107|    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), input.yaw * 0.62 * dt);
108|    this.quat.multiply(q);
109|
110|    this.updateVectors();
111|    const bank = Math.atan2(this.right.y, this.up.y);
112|    let rollRate = input.roll * 1.85;
113|    if (Math.abs(input.roll) < 0.05) rollRate += -bank * 1.25;
114|    q.setFromAxisAngle(new THREE.Vector3(0, 0, 1), rollRate * dt);
115|    this.quat.multiply(q);
116|    this.quat.normalize();
117|
118|    this.updateVectors();
119|
120|    // Coordinated turn from bank angle.
121|    const turnRate = Math.sin(this.bank) * 1.05;
122|    q.setFromAxisAngle(WORLD_UP, turnRate * dt);
123|    this.quat.multiply(q);
124|    this.quat.normalize();
125|    this.updateVectors();
126|
127|    // Translate with a touch of sink at low speed.
128|    const sink = Math.max(0, 46 - this.speed) * 0.22;
129|    this.pos.addScaledVector(this.forward, this.speed * dt);
130|    this.pos.y -= sink * dt;
131|    this.pos.y = Math.min(this.pos.y, 620);
132|    this.verticalSpeed = (this.pos.y - this.prevPos.y) / Math.max(dt, 0.0001);
133|    this.flash = Math.max(0, this.flash - dt * 1.8);
134|  }
